// SHELLY ADAPTER — command side (hot water).
// The dispatcher and the lockout loop send the Tuya-shaped {payload:{dps:'1', set:bool}} through
// hwv3.link.plugCmd. This turns it into Shelly RPC over MQTT (Gen2+ API: <prefix>/rpc).
//   ON  -> Switch.Set on:true with toggle_after = a DEAD-MAN: the relay switches itself OFF after
//          DEADMAN_S unless this node refreshes it. Refreshed on every 30 s tick while wanted ON,
//          so a dead Pi / Node-RED / Wi-Fi can never leave the element running for more than DEADMAN_S.
//   OFF -> Switch.Set on:false. Not re-asserted on the tick: the lockout loop already forces OFF
//          every 5 min outside the window, and a manual press inside it is left alone (same as Tuya).
// 'init' (once at start) sets the relay's power-on state to OFF and asks for its status.
const PREFIX    = '__SHELLY_PREFIX__';
const SWITCH_ID = __SHELLY_SWITCH_ID__;
const SRC       = '__SHELLY_SRC__';        // replies arrive on <SRC>/rpc
const DEADMAN_S = __SHELLY_DEADMAN_S__;

function rpc(method, params) {
  var id = (context.get('rpcId') || 0) + 1; context.set('rpcId', id);
  return { topic: PREFIX + '/rpc', payload: JSON.stringify({ id: id, src: SRC, method: method, params: params }) };
}
function setSwitch(on) {
  return rpc('Switch.Set', on ? { id: SWITCH_ID, on: true, toggle_after: DEADMAN_S } : { id: SWITCH_ID, on: false });
}
function status() { return rpc('Switch.GetStatus', { id: SWITCH_ID }); }

if (msg.topic === 'init') {
  return [[ rpc('Switch.SetConfig', { id: SWITCH_ID, config: { initial_state: 'off' } }), status() ]];
}
if (msg.topic === 'tick') {
  var out = [ status() ];
  if (context.get('want') === true) out.push(setSwitch(true));
  return [out];
}
var p = msg.payload;
if (p && typeof p === 'object' && p.set !== undefined) {
  var on = !!p.set;
  context.set('want', on);
  node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: 'sent ' + (on ? 'ON' : 'OFF') + ' ' + new Date().toLocaleTimeString() });
  return [[ setSwitch(on), status() ]];
}
return null;

// SHELLY ADAPTER — telemetry side (hot water).
// Reads Switch.GetStatus replies (<SRC>/rpc) and NotifyStatus change events (<prefix>/events/rpc) and
// republishes them on the SAME topics the Tuya bridge used, so the aggregator, dispatcher, lockout loop
// and relay need no change:  bsf/hotwater/plug_state (true/false)  bsf/hotwater/plug_power (W).
// Watts: the relay's own meter (apower) when METERED and reported; otherwise the element rating while ON.
// The dispatcher subtracts plug_power from the house load while the plug is on, so reporting 0 for a
// running element would make its own draw look like lost surplus and switch it straight back off.
const SWITCH_KEY = 'switch:' + __SHELLY_SWITCH_ID__;
const METERED    = __SHELLY_METERED__;
const RATED_W    = __SHELLY_RATED_W__;

var p = msg.payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { return null; } }
if (!p || typeof p !== 'object') return null;
if (p.error) {
  node.status({ fill: 'red', shape: 'ring', text: 'RPC error ' + p.error.code + ': ' + p.error.message });
  node.warn('shelly RPC error: ' + JSON.stringify(p.error));
  return null;
}
var st = null;
if (p.result && typeof p.result === 'object' && p.result.output !== undefined) st = p.result;          // GetStatus reply
else if (p.method === 'NotifyStatus' && p.params && p.params[SWITCH_KEY]) st = p.params[SWITCH_KEY];  // change event
if (!st) return null;
if (typeof st.apower === 'number' && isFinite(st.apower)) context.set('apower', st.apower);
var output = (typeof st.output === 'boolean') ? st.output : context.get('output');
if (typeof output !== 'boolean') return null;     // a power-only event before we know the switch state
context.set('output', output);
var ap = context.get('apower');
var w = !output ? 0 : ((METERED && typeof ap === 'number') ? ap : RATED_W);
w = Math.max(0, Math.round(w));
node.status({ fill: output ? 'green' : 'grey', shape: 'dot', text: (output ? 'ON ' + w + ' W' : 'OFF') + ' ' + new Date().toLocaleTimeString() });
return [ { topic: 'bsf/hotwater/plug_state', payload: output }, { topic: 'bsf/hotwater/plug_power', payload: w } ];
